css:
body{margin:0;background:#F6F4F0;font-family:'Archivo',system-ui,sans-serif;color:#1A1918}
a{color:#1A1918}a:hover{color:#6B6660}
.cap{font-size:12px;font-weight:500;letter-spacing:0.18em;text-transform:uppercase}
.wrap{max-width:1440px;margin:0 auto;padding:0 64px;box-sizing:border-box}
.ph{display:block;width:100%;height:100%;object-fit:cover}
.h1{margin:0;font-size:40px;font-weight:300;text-transform:uppercase;letter-spacing:0.03em;line-height:1.15}
.disp{margin:0;font-size:56px;font-weight:300;text-transform:uppercase;letter-spacing:0.03em;line-height:1.05}
.h2{font-size:28px;font-weight:300;text-transform:uppercase;letter-spacing:0.03em;line-height:1.15}
.body{font-size:16px;line-height:1.65;color:#6B6660}
.small{font-size:14px;line-height:1.55;color:#6B6660}
.tbl{width:100%;border-collapse:collapse;font-size:16px}
.tbl th,.tbl td{text-align:left;padding:14px 16px 14px 0;border-bottom:1px solid #DCD6CD;vertical-align:top}
.tbl th{font-weight:400;color:#6B6660}
.fld{display:flex;flex-direction:column;gap:6px;font-size:14px}
.fld input,.fld select,.fld textarea{padding:14px;border:1px solid #DCD6CD;background:#FFFFFF;font:inherit;color:#1A1918}
.btn{display:inline-block;background:#1A1918;color:#F6F4F0;border:0;padding:16px 22px;font:inherit;font-size:12px;font-weight:500;letter-spacing:0.18em;text-transform:uppercase;text-decoration:none;cursor:pointer}
@media (max-width:760px){.wrap{padding:0 20px}.disp{font-size:40px}.h1{font-size:28px}}
